<?php $title='Mitteilungen verwalten';$labels=['draft'=>'Entwurf','scheduled'=>'Geplant','published'=>'Veröffentlicht','archived'=>'Archiviert']; ?>
<div class="page-header split"><div><p class="eyebrow">Mitteilungen · Verwaltung</p><h1>Mitteilungen verwalten</h1><p>Entwürfe, geplante Veröffentlichungen, aktive und archivierte Mitteilungen.</p></div><a class="button primary" href="<?= e(url('announcements/create')) ?>">+ Mitteilung</a></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Titel</th><th>Priorität</th><th>Status</th><th>Gültigkeit</th><th>Version</th><th></th></tr></thead><tbody><?php foreach($items as $a):?><tr><td><strong><?= e($a['title']) ?></strong></td><td><?= e($a['priority']==='important'?'Wichtig':'Info') ?></td><td><span class="badge <?= $a['status']==='published'?'active':'neutral' ?>"><?= e($labels[$a['status']]??$a['status']) ?></span></td><td><?= e(format_datetime($a['valid_from'])) ?> – <?= e(format_datetime($a['valid_until'])) ?></td><td><?= (int)$a['revision'] ?></td><td class="align-right"><a class="button ghost compact" href="<?= e(url('announcements/'.$a['id'])) ?>">Öffnen</a> <a class="button ghost compact" href="<?= e(url('announcements/'.$a['id'].'/edit')) ?>">Bearbeiten</a></td></tr><?php endforeach;?><?php if($items===[]):?><tr><td colspan="6" class="empty">Noch keine Mitteilungen.</td></tr><?php endif;?></tbody></table></div></div>
